import{_ as s,o as i,c as a,a2 as t}from"./chunks/framework.KobcctIO.js";const u=JSON.parse('{"title":"Fournisseurs Cloud et Authentification","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/horizon/providers-and-auth.md","filePath":"fr/guide/horizon/providers-and-auth.md"}'),r={name:"fr/guide/horizon/providers-and-auth.md"};function n(o,e,l,d,p,h){return i(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="fournisseurs-cloud-et-authentification" tabindex="-1">Fournisseurs Cloud et Authentification <a class="header-anchor" href="#fournisseurs-cloud-et-authentification" aria-label="Permalink to &quot;Fournisseurs Cloud et Authentification&quot;">​</a></h1><div style="display:flex;gap:8px;margin:1rem 0;flex-wrap:wrap;"><img src="https://img.shields.io/badge/Pattern-Provider%20Factory-blue.svg" alt="Pattern"><img src="https://img.shields.io/badge/Fournisseurs-Google%20%7C%20Dropbox%20%7C%20OneDrive-green.svg" alt="Fournisseurs"><img src="https://img.shields.io/badge/S%C3%A9curit%C3%A9-Hardware--Bound%20Tokens-red.svg" alt="Sécurité"></div><p>Gens-Horizon a été conçu pour être totalement agnostique du service de stockage distant. Grâce au design pattern <strong>Factory</strong> implémenté dans <code>provider.js</code>, le moteur délègue toutes les opérations d&#39;entrée/sortie à des adaptateurs dédiés situés dans le dossier <code>/providers</code>.</p><hr><h2 id="_1-le-pattern-provider-factory-provider-js" tabindex="-1">1. Le Pattern Provider Factory (<code>provider.js</code>) <a class="header-anchor" href="#_1-le-pattern-provider-factory-provider-js" aria-label="Permalink to &quot;1. Le Pattern Provider Factory (`provider.js`)&quot;">​</a></h2><p>Chaque adaptateur cloud implémente une interface uniforme commune :</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> BaseCloudProvider</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    async</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> login</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() {}                           </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Déclenche le flux d&#39;autorisation OAuth2</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    async</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> getQuota</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() {}                         </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Retourne { total, used, free }</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    async</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> listFiles</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">prefix</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {}                  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Liste les deltas et métadonnées distants</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    async</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> uploadFile</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">localPath</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">remoteName</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {}  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Téléversement avec reprise</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    async</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> downloadFile</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">remoteName</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">destPath</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {} </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Téléchargement en flux direct</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    async</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> deleteFile</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">fileId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {}                 </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Suppression d&#39;un artefact distant</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    async</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> refreshTokenIfNeeded</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() {}             </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Renouvellement silencieux du bearer token</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>La fonction <code>getProvider(name)</code> instancie dynamiquement la classe appropriée en fonction du paramètre configuré dans <code>horizon_settings.json</code> :</p><ul><li><code>&#39;google&#39;</code> -&gt; <code>providers/google.js</code></li><li><code>&#39;dropbox&#39;</code> -&gt; <code>providers/dropbox.js</code></li><li><code>&#39;onedrive&#39;</code> -&gt; <code>providers/onedrive.js</code></li></ul><hr><h2 id="_2-implementations-specifiques" tabindex="-1">2. Implémentations Spécifiques <a class="header-anchor" href="#_2-implementations-specifiques" aria-label="Permalink to &quot;2. Implémentations Spécifiques&quot;">​</a></h2><h3 id="google-drive-providers-google-js" tabindex="-1">Google Drive (<code>providers/google.js</code>) <a class="header-anchor" href="#google-drive-providers-google-js" aria-label="Permalink to &quot;Google Drive (`providers/google.js`)&quot;">​</a></h3><ul><li>Utilise l&#39;API Google Drive v3 via des requêtes REST pures sans SDK tiers lourd.</li><li>Stocke les données de jeu dans un dossier d&#39;application dédié <code>GensHorizon/</code> à la racine de Google Drive (ou dans le conteneur privé <code>appDataFolder</code>).</li><li>Gère l&#39;upload en mode multipart pour les petits deltas et en upload résumable pour les consolidations volumineuses.</li></ul><h3 id="dropbox-providers-dropbox-js" tabindex="-1">Dropbox (<code>providers/dropbox.js</code>) <a class="header-anchor" href="#dropbox-providers-dropbox-js" aria-label="Permalink to &quot;Dropbox (`providers/dropbox.js`)&quot;">​</a></h3><ul><li>Utilise les endpoints de l&#39;API Dropbox v2 (<code>/2/files/upload</code>, <code>/2/files/download</code>).</li><li>Exploite le système de hash natif Dropbox pour valider l&#39;intégrité de bout en bout des fichiers transférés.</li><li>Gère les jetons d&#39;accès courts avec rafraîchissement automatique via le point d&#39;accès OAuth2 de Dropbox.</li></ul><h3 id="microsoft-onedrive-providers-onedrive-js" tabindex="-1">Microsoft OneDrive (<code>providers/onedrive.js</code>) <a class="header-anchor" href="#microsoft-onedrive-providers-onedrive-js" aria-label="Permalink to &quot;Microsoft OneDrive (`providers/onedrive.js`)&quot;">​</a></h3><ul><li>Utilise l&#39;API Microsoft Graph (<code>/me/drive/special/approot</code> ou dossier ciblé).</li><li>Intègre la création automatique de sessions de téléversement (<code>createUploadSession</code>) pour supporter les connexions réseau instables.</li></ul><hr><h2 id="_3-strategie-de-rejeu-et-tolerance-aux-pannes-retry-js" tabindex="-1">3. Stratégie de Rejeu et Tolérance aux Pannes (<code>retry.js</code>) <a class="header-anchor" href="#_3-strategie-de-rejeu-et-tolerance-aux-pannes-retry-js" aria-label="Permalink to &quot;3. Stratégie de Rejeu et Tolérance aux Pannes (`retry.js`)&quot;">​</a></h2><p>Pour faire face aux coupures de réseau transitoires, aux saturations de bande passante et aux limites de débit (<em>Rate Limiting</em> 429 ou erreurs 503), tous les appels réseau passent par un wrapper adaptatif :</p><ul><li><strong>Backoff Exponentiel :</strong> Délai initial (<code>retryBaseDelay: 1500 ms</code>) multiplié par un facteur avec injection d&#39;une variation aléatoire (<em>jitter</em>) pour éviter la tempête de requêtes simultanées.</li><li><strong>Nombre de Tentatives Configurable :</strong> Par défaut 3 tentatives avant déclaration d&#39;échec propre.</li><li><strong>Détection des Erreurs Fatales :</strong> Les erreurs d&#39;authentification définitive (401 non résolue après rafraîchissement) arrêtent immédiatement la boucle sans épuiser inutilement les quotas.</li></ul><hr><h2 id="_4-chiffrement-materiel-des-jetons-auth-js" tabindex="-1">4. Chiffrement Matériel des Jetons (<code>Auth.js</code>) <a class="header-anchor" href="#_4-chiffrement-materiel-des-jetons-auth-js" aria-label="Permalink to &quot;4. Chiffrement Matériel des Jetons (`Auth.js`)&quot;">​</a></h2><p>Les identifiants et jetons d&#39;accès distants ne sont <strong>jamais stockés en clair</strong> sur le disque de la machine :</p><ol><li>Au premier lancement, Gens-Horizon génère un identifiant machine unique et inviolable de 256 bits (<code>crypto.randomBytes(32)</code>) stocké dans <code>.machine_id</code>.</li><li>Un sel cryptographique indépendant de 16 octets est enregistré dans <code>salt.key</code> avec des droits d&#39;accès restreints (<code>mode: 0o600</code>).</li><li>Une clé symétrique de 256 bits est dérivée via <strong>PBKDF2</strong> à 600 000 itérations en utilisant le contenu de <code>.machine_id</code> comme mot de passe.</li><li>Les jetons OAuth2 sont chiffrés en <strong>AES-256-GCM</strong> avec un vecteur d&#39;initialisation (IV) de 12 octets renouvelé à chaque écriture.</li></ol><div class="tip custom-block"><p class="custom-block-title">Protection contre le vol de dossier</p><p>Même si un tiers venait à copier l&#39;intégralité du dossier Gens-Horizon sur une clé USB, il lui serait mathématiquement impossible de déchiffrer les jetons cloud sur une autre machine sans posséder le fichier système <code>.machine_id</code> propre au matériel d&#39;origine.</p></div>',26)])])}const k=s(r,[["render",n]]);export{u as __pageData,k as default};
